'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useState } from 'react'
import Box from '@mui/material/Box'
import Button from '@mui/material/Button'
import Card from '@mui/material/Card'
import IconButton from '@mui/material/IconButton'
import Tooltip from '@mui/material/Tooltip'
import AddIcon from '@mui/icons-material/Add'
import DeleteOutlined from '@mui/icons-material/DeleteOutlined'
import EditOutlined from '@mui/icons-material/EditOutlined'
import { useTranslations } from 'next-intl'
import { ApiError } from '@/lib/api/client'
import { usePermissions } from '@/lib/auth/permissions'
import { useFormat } from '@/lib/format'
import { useReference } from '@/lib/reference'
import { AppPage } from '@/components/app-page'
import { useConfirm } from '@/components/confirm-provider'
import { DataTable } from '@/components/data-table'
import type { Column } from '@/components/data-table'
import { SearchInput } from '@/components/search-input'
import { useToast } from '@/components/toast-provider'
import { useListParams } from '@/components/use-list-params'
import { useDeleteOrder, useOrderList } from './api'
import { OrderFormModal } from './order-form-modal'
import type { Order } from './types'

/** Hides a text visually while keeping it for screen readers. */
const srOnly = {
  border: 0,
  clip: 'rect(0 0 0 0)',
  height: '1px',
  margin: '-1px',
  overflow: 'hidden',
  padding: 0,
  position: 'absolute',
  whiteSpace: 'nowrap',
  width: '1px',
} as const

export function OrderPage() {
  const t = useTranslations('shop')
  const tCommon = useTranslations('common')
  const format = useFormat()
  const toast = useToast()
  const confirm = useConfirm()
  const reference = useReference()
  const { can } = usePermissions()
  const canManage = can('shop.manage')
  const { values, page, update } = useListParams(['q'] as const, { sort: 'id,asc' })
  const list = useOrderList({ ...values, page, size: reference.ui.pageSize })
  const remove = useDeleteOrder()
  const [editing, setEditing] = useState<Order | 'new' | null>(null)

  const onDelete = async (row: Order) => {
    const ok = await confirm({
      title: t('order.deleteTitle'),
      message: tCommon('deleteConfirmText'),
      confirmLabel: tCommon('delete'),
      danger: true,
    })
    if (!ok) return
    remove.mutate(row.id, {
      onSuccess: () => toast.success(tCommon('deleted')),
      onError: error => toast.error(error instanceof ApiError ? error.message : tCommon('unknownError')),
    })
  }

  const columns: Column<Order>[] = [
    {
      key: 'id',
      header: t('order.fields.id'),
      sortKey: 'id',
      align: 'right',
      nowrap: true,
      render: r => r.id != null ? format.number(r.id) : '–',
    },
    {
      key: 'orderedOn',
      header: t('order.fields.orderedOn'),
      sortKey: 'orderedOn',
      nowrap: true,
      render: r => r.orderedOn ? format.date(r.orderedOn) : '–',
    },
    {
      key: 'status',
      header: t('order.fields.status'),
      sortKey: 'status',
      nowrap: true,
      render: r => r.status ?? '–',
    },
    {
      key: 'customerId',
      header: t('order.fields.customerId'),
      align: 'right',
      nowrap: true,
      render: r => r.customerId != null ? format.number(r.customerId) : '–',
    },
    ...(canManage
      ? [
          {
            key: 'actions',
            header: <Box component="span" sx={srOnly}>{tCommon('actions')}</Box>,
            align: 'right' as const,
            nowrap: true,
            render: (r: Order) => (
              <>
                <Tooltip title={tCommon('edit')}>
                  <IconButton size="small" aria-label={tCommon('edit')} onClick={() => setEditing(r)}>
                    <EditOutlined fontSize="small" />
                  </IconButton>
                </Tooltip>
                <Tooltip title={tCommon('delete')}>
                  <span>
                    <IconButton
                      size="small"
                      color="error"
                      aria-label={tCommon('delete')}
                      disabled={!r.deletable}
                      onClick={() => onDelete(r)}
                    >
                      <DeleteOutlined fontSize="small" />
                    </IconButton>
                  </span>
                </Tooltip>
              </>
            ),
          },
        ]
      : []),
  ]

  return (
    <AppPage title={t('order.title')}>
      <Card>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, alignItems: 'center', p: 2, borderBottom: 1, borderColor: 'divider' }}>
          <SearchInput value={values.q} onChange={q => update({ q })} placeholder={t('order.search')} />
          {canManage && (
            <Box sx={{ ml: 'auto' }}>
              <Button variant="contained" startIcon={<AddIcon />} onClick={() => setEditing('new')}>
                {t('order.new')}
              </Button>
            </Box>
          )}
        </Box>
        <DataTable
          columns={columns}
          page={list.data}
          rowKey={r => r.id}
          isLoading={list.isFetching}
          error={list.error}
          onRetry={() => list.refetch()}
          sort={values.sort}
          onSortChange={sort => update({ sort })}
          onPageChange={p => update({ page: p })}
          emptyTitle={t('order.empty')}
        />
      </Card>
      {editing && <OrderFormModal row={editing === 'new' ? null : editing} onClose={() => setEditing(null)} />}
    </AppPage>
  )
}
